def transform(grid):
    out = [row[:] for row in grid]
    # The patterned cells alternate marker/background; recolor each
    # background cell immediately preceding a marker.
    marker = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    background = min(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    for r, row in enumerate(grid):
        for c in range(len(row) - 1):
            if row[c] == background and row[c + 1] == marker:
                out[r][c] = 2
    return out
