def transform(grid):
    out = [row[:] for row in grid]
    # Find the common background value; recolor background cells between
    # matching non-background cells in each horizontal alternating stripe.
    background = max({v for row in grid for v in row},
                     key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] != background and row[c + 1] == row[c - 1]:
                out[r][c] = 2
    return out
